from __future__ import annotations
import os
import sys

# bash redirects the answer file onto fd 3 via `3>file`. Move it to a private
# fd and close fd 3 itself so user code can't accidentally write or close it.
# After solve() returns, the wrapper writes the serialized result through the
# private fd.
_answer_fd = os.dup(3)
os.close(3)

{{.}}

def _serialize(result):
    if isinstance(result, (list, tuple)):
        return " ".join(str(x) for x in result)
    return str(result)

if __name__ == "__main__":
    line = sys.stdin.readline().rstrip("\n")
    nums = [int(x) for x in line.split()]
    result = solve(nums)
    os.write(_answer_fd, _serialize(result).encode())
    os.close(_answer_fd)

