def solve(nums: list[int]) -> list[int]:
    # nums[0] is the target. nums[1:] is the array to search.
    # Return [i, j] (i < j): 0-based indices into nums[1:] such that
    # nums[1:][i] + nums[1:][j] == target.
    target = nums[0]
    arr = nums[1:]
    seen = {}
    for i, x in enumerate(arr):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

