    string payload;
    for (size_t i = 0; i < result.size(); ++i) {
        if (i) payload += ' ';
        payload += to_string(result[i]);
    }
    write(_answer_fd, payload.c_str(), payload.size());
    close(_answer_fd);
    return 0;
}

