// nums[0] is the target; nums[1..] is the array. Return the 0-based indices
// (i, j) with i < j of two distinct elements in nums[1..] whose sum equals
// the target.
vector<int> solve(vector<long long> nums) {
    long long target = nums[0];
    int n = (int)nums.size() - 1;
    unordered_map<long long, int> seen;
    for (int i = 0; i < n; ++i) {
        long long x = nums[1 + i];
        auto it = seen.find(target - x);
        if (it != seen.end()) return {it->second, i};
        seen[x] = i;
    }
    return {};
}

