package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
	"syscall"
)

{{.}}

func main() {
	// Move bash-supplied fd 3 to a private fd and close fd 3 so user code
	// can't poke at it. The duplicate is used to deliver the answer below.
	dupFd, _ := syscall.Dup(3)
	_ = syscall.Close(3)
	answer := os.NewFile(uintptr(dupFd), "answer")

	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	line = strings.TrimRight(line, "\n")

	fields := strings.Fields(line)
	nums := make([]int64, len(fields))
	for i, f := range fields {
		v, _ := strconv.ParseInt(f, 10, 64)
		nums[i] = v
	}

	result := solve(nums)

	parts := make([]string, len(result))
	for i, x := range result {
		parts[i] = fmt.Sprint(x)
	}
	payload := strings.Join(parts, " ")

	_, _ = answer.WriteString(payload)
	_ = answer.Close()
}

