// nums[0] is the target; nums[1:] is the array. Return the 0-based indices
// (i, j) with i < j of two distinct elements in nums[1:] whose sum equals
// the target.
func solve(nums []int64) []int {
	target := nums[0]
	arr := nums[1:]
	seen := make(map[int64]int)
	for i, x := range arr {
		if j, ok := seen[target-x]; ok {
			return []int{j, i}
		}
		seen[x] = i
	}
	return nil
}
